import{_ as n,o as i,c as t,aj as e,j as o}from"./chunks/framework.C6uXqnaX.js";const f=JSON.parse('{"title":"Angular Internationalization (i18n)","description":"","frontmatter":{},"headers":[],"relativePath":"en/guide/i18n.md","filePath":"en/guide/i18n.md"}'),r={name:"en/guide/i18n.md"};function l(s,a,d,c,u,g){return i(),t("div",null,a[0]||(a[0]=[e('<h1 id="angular-internationalization-i18n" tabindex="-1">Angular Internationalization (i18n) <a class="header-anchor" href="#angular-internationalization-i18n" aria-label="Permalink to &quot;Angular Internationalization (i18n)&quot;">​</a></h1><p><em>Internationalization</em>, sometimes referenced as i18n, is the process of designing and preparing your project for use in different locales around the world. <em>Localization</em> is the process of building versions of your project for different locales. The localization process includes the following actions.</p><ul><li>Extract text for translation into different languages</li><li>Format data for a specific locale</li></ul><p>A <em>locale</em> identifies a region in which people speak a particular language or language variant. Possible regions include countries and geographical regions. A locale determines the formatting and parsing of the following details.</p><ul><li>Measurement units including date and time, numbers, and currencies</li><li>Translated names including time zones, languages, and countries</li></ul><p>For a quick introduction to localization and internationalization watch this video:</p>',6),o("iframe",{src:"https://www.youtube.com/embed/KNTN-nsbV7M",title:"Video",style:{width:"100%","aspect-ratio":"16/9",border:"0"},allowfullscreen:""},null,-1),e('<h2 id="learn-about-angular-internationalization" tabindex="-1">Learn about Angular internationalization <a class="header-anchor" href="#learn-about-angular-internationalization" aria-label="Permalink to &quot;Learn about Angular internationalization&quot;">​</a></h2><ul><li><a href="/en/guide/i18n/add-package"><strong>Add the localize package</strong></a>: Learn how to add the Angular Localize package to your project</li><li><a href="/en/guide/i18n/locale-id"><strong>Refer to locales by ID</strong></a>: Learn how to identify and specify a locale identifier for your project</li><li><a href="/en/guide/i18n/format-data-locale"><strong>Format data based on locale</strong></a>: Learn how to implement localized data pipes and override the locale for your project</li><li><a href="/en/guide/i18n/prepare"><strong>Prepare component for translation</strong></a>: Learn how to specify source text for translation</li><li><a href="/en/guide/i18n/translation-files"><strong>Work with translation files</strong></a>: Learn how to review and process translation text</li><li><a href="/en/guide/i18n/merge"><strong>Merge translations into the application</strong></a>: Learn how to merge translations and build your translated application</li><li><a href="/en/guide/i18n/deploy"><strong>Deploy multiple locales</strong></a>: Learn how to deploy multiple locales for your application</li><li><a href="/en/guide/i18n/import-global-variants"><strong>Import global variants of the locale data</strong></a>: Learn how to import locale data for language variants</li><li><a href="/en/guide/i18n/manage-marked-text"><strong>Manage marked text with custom IDs</strong></a>: Learn how to implement custom IDs to help you manage your marked text</li><li><a href="/en/guide/i18n/example"><strong>Internationalization example</strong></a>: Review an example of Angular internationalization.</li></ul>',2)]))}const m=n(r,[["render",l]]);export{f as __pageData,m as default};
